L19_1.m_Talk_KOREA = "아니, 그보다! 그럼, 스폰서와의 계약은 어쩌시게요?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "いや、それより！　じゃあ、スポンサーとの契約はどうするんですか？"
L19_1.m_Talk_ENG = "No, besides that! Then, what about the contract with the sponsor?"
L19_1.m_Talk_TWN = "不，比起這個！那和贊助商的合同怎麼辦？"
