L20_1.m_Crash = 20
L20_1.m_Talk_KOREA = "그렇게 멋대로 결말을 내버리면, 저희에게 막대한 위약금을 요구할 텐데요……?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "そうやって勝手に結末を決めたら、私たちに莫大な違約金を要求してくるんじゃ……？"
L20_1.m_Talk_ENG = "If you end it like that, they're going to ask for a huge settlement."
