L22_1.m_Talk_KOREA = "상관없습니다. 제가 없는 자리에서 발생한 계약 사항 따위 관심 없으니까요."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "私には関係ありません。私がいないところで発生した契約事項なんて、興味ありませんから。"
L22_1.m_Talk_ENG = "No matter. I'm not interested in a contract that happened when I wasn't present."
L22_1.m_Talk_TWN = "無所謂。我不在場時簽署的合同還輪不到我來操心。"
L22_1.m_Talk_SCN = "无所谓。我不在场时签署的合同还轮不到我来操心。"
L22_1.m_Talk_DEU = "No matter. I'm not interested in a contract that happened when I wasn't present."
L22_1.m_Talk_FRA = "No matter. I'm not interested in a contract that happened when I wasn't present."
