L44_1 = "<color=#ffd34c>■■■</color> 아무래도 이건 힘들겠는데?\n<color=#ffd34c>■■</color> ㅇㅇ 애초에 방어팀이 너무 사기임 ㅋㅋㅋㅋ\n<color=#ffd34c>■■ ■</color> 안 돼!! 나 이번에 카나리아에 역배 걸었다고!!\n<color=#ffd34c>■■■</color> 아쉽네, 진짜 여기까지 와서 떨어지나."
L43_1.m_SubTitle_KOREA = L44_1
L43_1.m_fSubTitleTalkTime = 0
L44_1 = "<color=#ffd34c>■■■</color> さすがにダメっぽくない？\n<color=#ffd34c>■■</color> ああ、そもそも防御チームがチートすぎるんだよなｗｗｗ\n<color=#ffd34c>■■ ■</color> まじかよ！！　この試合、カナリアにベットしたのに！！\n<color=#ffd34c>■■■</color> 残念だな、ここまで来たのに敗退だなんて。"
L43_1.m_SubTitle_JPN = L44_1
L44_1 = "<color=#ffd34c>■■■</color> I think it's gonna be difficult.\n<color=#ffd34c>■■</color> Yeah, the defense team is OP. LOL!\n<color=#ffd34c>■■ ■</color> No!! I bet everything on Canary this time!!\n<color=#ffd34c>■■■</color> What a shame to end it here."
L43_1.m_SubTitle_ENG = L44_1
L44_1 = "<color=#ffd34c>■■■</color> 感覺有點困難欸？\n<color=#ffd34c>■■</color> 嗯嗯，防守方從一開始就耍詐，呵呵呵\n<color=#ffd34c>■■ ■</color> 不可以！我這次賭金絲雀會贏欸！！\n<color=#ffd34c>■■■</color> 真可惜，就在這裡止步嗎？"
L43_1.m_SubTitle_TWN = L44_1
L44_1 = "<color=#ffd34c>■■■</color>应该很难吧？\n<color=#ffd34c>■■</color>没错，防御队也太厉害了，呵呵呵\n<color=#ffd34c>■■ ■</color>不要啊！我这次押了金丝雀啊！！\n<color=#ffd34c>■■■</color>好可惜，都来到这一步了，不会就这么淘汰了吧。"
L43_1.m_SubTitle_SCN = L44_1
L44_1 = "<color=#ffd34c>■■■</color> I think it's gonna be difficult.\n<color=#ffd34c>■■</color> Yeah, the defense team is OP. LOL!\n<color=#ffd34c>■■ ■</color> No!! I bet everything on Canary this time!!\n<color=#ffd34c>■■■</color> What a shame to end it here."
L43_1.m_SubTitle_DEU = L44_1
L44_1 = "<color=#ffd34c>■■■</color> I think it's gonna be difficult.\n<color=#ffd34c>■■</color> Yeah, the defense team is OP. LOL!\n<color=#ffd34c>■■ ■</color> No!! I bet everything on Canary this time!!\n<color=#ffd34c>■■■</color> What a shame to end it here."
