L3_1.m_CharScale = L4_1
L3_1.m_CharScaleTime = 0.01
L4_1 = "세계가 변화를 맞이하고 세피라가 지상에 강림한 순간, 당신들 또한 그곳에 있었어요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "世界が変化を迎え、セフィラが地上に降臨した瞬間にあなたたちもまたそこにいました。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "When the world changed and Sephira descended to earth, you were also there."
L3_1.m_Talk_ENG = L4_1
L4_1 = "世界迎來變化，塞菲拉降臨人世的那一刻，你們也在那裡。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "世界迎来变化，塞菲拉降临人世的那一刻，你们也在那里。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "When the world changed and Sephira descended to earth, you were also there."
L3_1.m_Talk_DEU = L4_1
L4_1 = "When the world changed and Sephira descended to earth, you were also there."
