L4_1.m_CharScale = L5_1
L4_1.m_CharScaleTime = 0.01
L5_1 = "그리고 그것이 <color=#ffd34c>당신</color>의 의지든, <color=#ffd34c>당신들</color>의 의지든 저 아이를 노리는 건, 틀림없이 우연이 아니겠죠."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そしてそれが<color=#ffd34c>あなた</color>の意志だろうと、<color=#ffd34c>あなたたち</color>の意志だろうと、あの子を狙っているのはきっと偶然ではないのでしょう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Whether that was <color=#ffd34c>your</color> will or <color=#ffd34c>your kind's</color> will, targeting that child can't be a coincidence."
L4_1.m_Talk_ENG = L5_1
L5_1 = "而且無論是<color=#ffd34c>你</color>的意志，還是<color=#ffd34c>你們</color>的意志，盯上那個孩子，絕對不是偶然。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "而且无论是<color=#ffd34c>你</color>的意志，还是<color=#ffd34c>你们</color>的意志，盯上那个孩子，绝对不是偶然。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Whether that was <color=#ffd34c>your</color> will or <color=#ffd34c>your kind's</color> will, targeting that child can't be a coincidence."
