L6_1.m_Face = "UNIT_HATE"
L6_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "마치, 백과 흑, 명과 암, 그리고 앞면과 뒷면처럼."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "まるで白と黒、明と暗、そして表と裏のように。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Much like black and white, light and shadow, or even the two side of one coin."
L6_1.m_Talk_ENG = L7_1
L7_1 = "就像白與黑，明與暗，以及正面與反面一樣。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "就像白与黑，明与暗，以及正面与反面一样。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Much like black and white, light and shadow, or even the two side of one coin."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Much like black and white, light and shadow, or even the two side of one coin."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SWANSONG_ACT3_STAGE2_START@257#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 257
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 6800305
L7_1.m_CutScenStrID = "SWANSONG_ACT3_STAGE2_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "당신들은 완벽히 상반되면서도 동시에 서로가 서로를 끌어들이고 있어요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あなたたちは完璧に相反しながらも同時にお互いを引き寄せています。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You two are the complete opposite, and yet drawn to each other."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你們雖然完全相反，但同時又彼此吸引。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "你们虽然完全相反，但同时又彼此吸引。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "You two are the complete opposite, and yet drawn to each other."
L7_1.m_Talk_DEU = L8_1
L8_1 = "You two are the complete opposite, and yet drawn to each other."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SWANSONG_ACT3_STAGE2_START@258#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 258
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 6800305
L8_1.m_CutScenStrID = "SWANSONG_ACT3_STAGE2_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_SERIOUS"
L8_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "그렇다는 말은 당신들 또한 <color=#ffd34c>세계를 만드는 법칙</color>에 의해 발생한 존재라는 거겠죠."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ということは、あなたたちもまた<color=#ffd34c>世界を作る法則</color>によって発生した存在だということでしょう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "That means that you are also beings created by <color=#ffd34c>the law of creating a world</color>."
L8_1.m_Talk_ENG = L9_1
L9_1 = "那就是說，你們也是<color=#ffd34c>創造世界的法則</color>所產生的存在吧。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "那就是说，你们也是<color=#ffd34c>创造世界的规则</color>所产生的存在吧。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "That means that you are also beings created by <color=#ffd34c>the law of creating a world</color>."
L8_1.m_Talk_DEU = L9_1
L9_1 = "That means that you are also beings created by <color=#ffd34c>the law of creating a world</color>."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SWANSONG_ACT3_STAGE2_START@259#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 259
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 6800305
L9_1.m_CutScenStrID = "SWANSONG_ACT3_STAGE2_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "물론, 그 힘의 반작용에 의해 생성된 찌꺼기에 불과하겠지만."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "もちろん、その力の反作用によって生成された残りかすに過ぎないでしょうけど。"
